//! Requests generated by py-opendisplay itself (`fixtures/make_client_vectors.py`)
//! replayed through [`Server`].
//!
//! Every response is also written to `client-responses.txt` in Cargo's test
//! scratch directory, and `fixtures/check_client_responses.py` feeds those back
//! through the client's own parsers (`build.sh test` runs it when the client's
//! venv exists). Together the two directions show the client and the server
//! agree byte for byte.

mod common;

use std::collections::BTreeMap;
use std::fmt::Write as _;

use common::{FakeDevice, board_config, exchange, reassemble_config};
use miniz_oxide::inflate::decompress_to_vec_zlib;
use opendisplay_proto::server::RefreshOutcome;
use opendisplay_proto::wire::DeepSleepError;
use opendisplay_proto::{RefreshMode, Server, mdns};

const VECTORS: &str = include_str!("fixtures/client-vectors.txt");
const CLIENT_FRAME: &[u8] = include_bytes!("fixtures/client-frame.zlib");

fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
        .collect()
}

/// Request frames by label, in file order.
fn vectors() -> BTreeMap<&'static str, Vec<Vec<u8>>> {
    let mut map: BTreeMap<_, Vec<_>> = BTreeMap::new();
    for line in VECTORS.lines() {
        let (label, bytes) = line.split_once(' ').unwrap();
        map.entry(label).or_default().push(hex(bytes));
    }
    map
}

fn one<'a>(vectors: &'a BTreeMap<&str, Vec<Vec<u8>>>, label: &str) -> &'a [u8] {
    let frames = &vectors[label];
    assert_eq!(frames.len(), 1, "{label}");
    &frames[0]
}

/// A server and device, plus a `label hex` transcript of every response for
/// the Python check.
struct Session {
    server: Server,
    device: FakeDevice,
    transcript: String,
}

impl Session {
    fn send(&mut self, label: &str, request: &[u8]) -> Vec<Vec<u8>> {
        let frames = exchange(&mut self.server, &mut self.device, request);
        self.record(label, &frames);
        frames
    }

    fn refresh(&mut self, label: &str, outcome: RefreshOutcome) -> Vec<Vec<u8>> {
        let mut frames = Vec::new();
        self.server
            .refresh_finished(outcome, &mut |frame| frames.push(frame.to_vec()));
        self.record(label, &frames);
        frames
    }

    fn record(&mut self, label: &str, frames: &[Vec<u8>]) {
        for frame in frames {
            let hex: String = frame.iter().map(|byte| format!("{byte:02x}")).collect();
            writeln!(self.transcript, "{label} {hex}").unwrap();
        }
    }

    fn save(&self) {
        let path = concat!(env!("CARGO_TARGET_TMPDIR"), "/client-responses.txt");
        std::fs::write(path, &self.transcript).unwrap();
    }
}

#[test]
fn client_session_end_to_end() {
    let v = vectors();
    let mut s = Session {
        server: Server::new(),
        device: FakeDevice::new(),
        transcript: String::new(),
    };
    let ack = |opcode: u8| vec![vec![0x00, opcode]];

    // Interrogation: version, status record, config.
    s.send("fw_version", one(&v, "fw_version"));
    s.send("read_msd", one(&v, "read_msd"));
    s.device.config = Some(board_config());
    let frames = s.send("read_config", one(&v, "read_config"));
    assert_eq!(reassemble_config(&frames), board_config());

    // The client rewrites the config it read, in 200-byte chunks.
    assert_eq!(s.send("config_write", one(&v, "config_write")), ack(0x41));
    for chunk in &v["config_chunk"] {
        assert_eq!(s.send("config_chunk", chunk), ack(0x42));
    }
    assert_eq!(
        s.device.written_config.as_deref(),
        Some(one(&v, "config_blob"))
    );

    // LAN upload of the image prepare_image() made from our config.
    let expected = decompress_to_vec_zlib(CLIENT_FRAME).unwrap();
    assert_eq!(expected.len(), common::FRAME_LEN);
    let start = one(&v, "lan_start");
    assert!(start.len() <= 200);
    assert_eq!(s.send("lan_start", start), ack(0x70));
    assert!(v["lan_data"].len() > 1);
    for chunk in &v["lan_data"] {
        assert_eq!(s.send("lan_data", chunk), ack(0x71));
    }
    assert_eq!(s.send("lan_end", one(&v, "lan_end")), ack(0x72));
    assert!(s.device.frame == expected);
    assert_eq!(s.refresh("refresh", RefreshOutcome::Done), ack(0x73));
    assert_eq!(s.server.displayed_etag(), Some(0x1234_ABCD));

    // The same image uncompressed in BLE-sized chunks, fast refresh.
    s.device.frame.fill(0xEE);
    assert_eq!(s.send("ble_start", one(&v, "ble_start")), ack(0x70));
    let mut chunks = expected
        .chunks(230)
        .map(|chunk| [&[0x00, 0x71], chunk].concat());
    let first = chunks.next().unwrap();
    assert_eq!(first, one(&v, "ble_data_first"));
    for chunk in std::iter::once(first).chain(chunks) {
        assert_eq!(s.send("ble_data", &chunk), ack(0x71));
    }
    assert_eq!(s.send("ble_end", one(&v, "ble_end")), ack(0x72));
    assert!(s.device.frame == expected);
    assert_eq!(s.device.refreshed, Some(RefreshMode::Fast));
    assert_eq!(
        s.refresh("refresh_timeout", RefreshOutcome::TimedOut),
        ack(0x74)
    );

    // Power and auth.
    assert_eq!(
        s.send("power_off", one(&v, "power_off")),
        [vec![0xFF, 0x52, 0x00, 0x00]]
    );
    assert_eq!(
        s.send("auth_step1", one(&v, "auth_step1")),
        [vec![0x00, 0x50, 0x03]]
    );
    s.device.sleep_answer = Some(DeepSleepError::Disabled);
    assert_eq!(
        s.send("deep_sleep_refused", one(&v, "deep_sleep_300")),
        [vec![0xFF, 0x53, 0x01, 0x00]]
    );
    s.device.sleep_answer = None;
    assert!(s.send("deep_sleep", one(&v, "deep_sleep_300")).is_empty());
    assert_eq!(s.device.slept, Some(Some(300)));
    assert!(
        s.send("deep_sleep", one(&v, "deep_sleep_default"))
            .is_empty()
    );
    assert_eq!(s.device.slept, Some(None));
    assert!(s.send("reboot", one(&v, "reboot")).is_empty());
    assert!(s.device.rebooted);

    s.save();
}

/// The service the firmware advertises for this board, with sample addresses.
const MDNS_SERVICE: mdns::Service<'static> = mdns::Service {
    instance: "ODCAED44",
    host: "ODCAED44",
    port: 2446,
    address: [192, 168, 50, 204],
    txt: &[
        "mac=94:a9:90:ca:ed:46",
        "tls=0",
        "fw=0.1",
        "cm=04",
        "pv=2.2",
    ],
};

/// zeroconf's own queries answered; the packets go to `mdns-responses.txt` for
/// `check_client_responses.py`, which parses them with zeroconf.
#[test]
fn mdns_answers_zeroconf_queries() {
    let v = vectors();
    let mut transcript = String::new();
    let mut out = [0u8; 512];
    for label in ["mdns_browse", "mdns_resolve"] {
        let len = mdns::respond(one(&v, label), &MDNS_SERVICE, false, &mut out)
            .unwrap_or_else(|| panic!("no answer to {label}"));
        let hex: String = out[..len].iter().map(|b| format!("{b:02x}")).collect();
        writeln!(transcript, "{label} {hex}").unwrap();
    }
    for (label, goodbye) in [("mdns_announce", false), ("mdns_goodbye", true)] {
        let len = mdns::announce(&MDNS_SERVICE, goodbye, &mut out).unwrap();
        let hex: String = out[..len].iter().map(|b| format!("{b:02x}")).collect();
        writeln!(transcript, "{label} {hex}").unwrap();
    }
    let path = concat!(env!("CARGO_TARGET_TMPDIR"), "/mdns-responses.txt");
    std::fs::write(path, transcript).unwrap();
}

/// A telemetry record with every field set, for py-opendisplay to decode
/// against the board config's sensor declarations (`check_msd.py`).
#[test]
fn telemetry_record_for_the_client() {
    use opendisplay_proto::msd::{Ambient, Telemetry, txt};
    let record = Telemetry {
        battery_mv: Some(4_172),
        chip_temp_c: Some(31),
        ambient: Some(Ambient {
            temp_deci: -55,
            rh_deci: 335,
        }),
        rebooted: true,
        counter: 5,
    }
    .encode();
    let hex: String = record.iter().map(|byte| format!("{byte:02x}")).collect();
    let txt = String::from_utf8(txt(&record).to_vec()).unwrap();
    let path = concat!(env!("CARGO_TARGET_TMPDIR"), "/msd-telemetry.txt");
    std::fs::write(path, format!("record {hex}\ntxt {txt}\n")).unwrap();
}
